-- Applied to production Supabase on 2026-10-26.
alter table public.profiles add column if not exists show_group_steps boolean not null default true, add column if not exists show_group_protein boolean not null default false, add column if not exists show_active_today boolean not null default true;
create table if not exists public.cheers(id uuid primary key default gen_random_uuid(),from_user_id uuid not null references public.profiles(id) on delete cascade,to_user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),constraint cheers_not_self check(from_user_id<>to_user_id));
create unique index if not exists cheers_sender_recipient_day_idx on public.cheers(from_user_id,to_user_id,((created_at at time zone 'Africa/Nairobi')::date));
alter table public.cheers enable row level security;
create policy "cheers: recipient read" on public.cheers for select to authenticated using ((select auth.uid())=to_user_id or (select auth.uid())=from_user_id);
create policy "cheers: sender insert" on public.cheers for insert to authenticated with check ((select auth.uid())=from_user_id and from_user_id<>to_user_id);
grant select,insert on public.cheers to authenticated;

create or replace function public.get_active_today(p_local_date date) returns table(user_id uuid,display_name text,avatar_url text,streak integer,last_activity timestamptz,group_id uuid)
language sql stable security definer set search_path='' as $$
with viewer_groups as(select group_id from public.group_members where user_id=(select auth.uid())),shared as(select gm.user_id,gm.group_id,count(*) over(partition by gm.group_id) group_size from public.group_members gm join viewer_groups vg on vg.group_id=gm.group_id),candidates as(select distinct on(s.user_id)s.user_id,s.group_id from shared s join public.profiles p on p.id=s.user_id where(p.show_active_today or p.id=(select auth.uid())) order by s.user_id,s.group_size desc,s.group_id),activity as(select c.user_id,c.group_id,greatest(coalesce((select max(ds.synced_at) from public.daily_steps ds where ds.user_id=c.user_id and ds.step_date=p_local_date and ds.steps>0),'-infinity'::timestamptz),coalesce((select max(pl.logged_at) from public.protein_logs pl where pl.user_id=c.user_id and pl.log_date=p_local_date and pl.grams>0),'-infinity'::timestamptz)) last_activity from candidates c)
select p.id,p.display_name,p.avatar_url,case when p.id=(select auth.uid()) or p.show_group_steps then greatest(coalesce(p.step_streak,p.streak,0),0) else null end,a.last_activity,a.group_id from activity a join public.profiles p on p.id=a.user_id where a.last_activity>'-infinity'::timestamptz order by(p.id=(select auth.uid())) desc,a.last_activity desc limit 20;$$;
revoke all on function public.get_active_today(date) from public,anon; grant execute on function public.get_active_today(date) to authenticated;

create or replace function public.get_group_member_profile(p_user_id uuid,p_group_id uuid,p_local_date date) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_shared boolean;v_steps boolean;v_protein boolean;v_result jsonb;v_group uuid;v_rank bigint;v_week date;
begin if v_uid is null then raise exception 'Authentication required';end if;select exists(select 1 from public.group_members a join public.group_members b on b.group_id=a.group_id where a.user_id=v_uid and b.user_id=p_user_id) into v_shared;if not v_shared and v_uid<>p_user_id then raise exception 'Not a shared group member';end if;select show_group_steps,show_group_protein into v_steps,v_protein from public.profiles where id=p_user_id;v_steps:=v_steps or v_uid=p_user_id;v_protein:=v_protein or v_uid=p_user_id;if p_group_id is not null and exists(select 1 from public.group_members where group_id=p_group_id and user_id=v_uid) and exists(select 1 from public.group_members where group_id=p_group_id and user_id=p_user_id) then v_group:=p_group_id;else select a.group_id into v_group from public.group_members a join public.group_members b on b.group_id=a.group_id where a.user_id=v_uid and b.user_id=p_user_id order by(select count(*) from public.group_members x where x.group_id=a.group_id) desc,a.group_id limit 1;end if;v_week:=p_local_date-(extract(isodow from p_local_date)::int-1);if v_steps then select l.rank into v_rank from public.get_group_leaderboard(v_group,'this_week',1000,0) l where l.user_id=p_user_id;end if;
select jsonb_strip_nulls(jsonb_build_object('id',p.id,'name',coalesce(nullif(trim(p.display_name),''),'Protlys member'),'avatar_url',p.avatar_url,'joined_at',p.created_at,'founding_member',exists(select 1 from public.group_members fm join public.groups fg on fg.id=fm.group_id where fm.user_id=p.id and fg.is_system and fg.name='Founding 250'),'streak',case when v_steps then greatest(coalesce(p.step_streak,p.streak,0),0) end,'steps_week',case when v_steps then(select coalesce(sum(ds.steps),0)::bigint from public.daily_steps ds where ds.user_id=p.id and ds.step_date between v_week and v_week+6 and not coalesce(ds.is_flagged,false))end,'group_rank',case when v_steps then v_rank end,'last7',case when v_steps then(select jsonb_agg(jsonb_build_object('date',d::date,'steps',coalesce(ds.steps,0))order by d)from generate_series(p_local_date-6,p_local_date,'1 day')d left join public.daily_steps ds on ds.user_id=p.id and ds.step_date=d::date)end,'protein_today',case when v_protein then(select coalesce(sum(pl.grams),0)::bigint from public.protein_logs pl where pl.user_id=p.id and pl.log_date=p_local_date)end,'protein_goal',case when v_protein then p.target_g end,'challenges_joined',(select count(*)::bigint from public.challenge_members cm join public.challenges c on c.id=cm.challenge_id where cm.user_id=p.id and p_local_date between c.start_date and c.end_date),'cheered_today',exists(select 1 from public.cheers ch where ch.from_user_id=v_uid and ch.to_user_id=p.id and(ch.created_at at time zone 'Africa/Nairobi')::date=p_local_date),'group_id',v_group))into v_result from public.profiles p where p.id=p_user_id;return v_result;end;$$;
revoke all on function public.get_group_member_profile(uuid,uuid,date) from public,anon;grant execute on function public.get_group_member_profile(uuid,uuid,date) to authenticated;

create or replace function public.cheer_member(p_to_user_id uuid,p_local_date date) returns uuid language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_id uuid;v_name text;begin if v_uid is null then raise exception 'Authentication required';end if;if v_uid=p_to_user_id then raise exception 'You cannot cheer yourself';end if;if not exists(select 1 from public.group_members a join public.group_members b on b.group_id=a.group_id where a.user_id=v_uid and b.user_id=p_to_user_id)then raise exception 'Not a shared group member';end if;if exists(select 1 from public.cheers c where c.from_user_id=v_uid and c.to_user_id=p_to_user_id and(c.created_at at time zone 'Africa/Nairobi')::date=p_local_date)then raise exception 'Already cheered today';end if;insert into public.cheers(from_user_id,to_user_id)values(v_uid,p_to_user_id)returning id into v_id;select coalesce(nullif(trim(display_name),''),'A group member')into v_name from public.profiles where id=v_uid;insert into public.notifications(user_id,type,title,body,is_read,created_at)values(p_to_user_id,'cheer','New cheer',v_name||' cheered you 👏',false,now());return v_id;end;$$;
revoke all on function public.cheer_member(uuid,date) from public,anon;grant execute on function public.cheer_member(uuid,date) to authenticated;
